<script setup lang="ts">
import { localizeAdminLabel, localizeAdminValue } from "../display";

export type AdminColumn = { key: string; label: string; priority?: "primary" | "secondary"; sensitive?: boolean };
defineProps<{ caption: string; columns: AdminColumn[]; rows: Array<Record<string, unknown>>; rowKey: string; selected?: string[]; loading?: boolean }>();
defineEmits<{ select: [keys: string[]] }>();
</script>
<template><div class="v-admin-table" :aria-busy="loading || undefined"><table><caption>{{ caption }}</caption><thead><tr><th v-if="selected" scope="col"><span class="sr-only">选择</span></th><th v-for="column in columns" :key="column.key" scope="col" :data-priority="column.priority ?? 'secondary'">{{ localizeAdminLabel(column.key, column.label) }}</th><th v-if="$slots.actions" scope="col">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="String(row[rowKey])"><td v-if="selected"><input type="checkbox" :aria-label="`选择 ${String(row[rowKey])}`" :checked="selected.includes(String(row[rowKey]))" @change="$emit('select', selected.includes(String(row[rowKey])) ? selected.filter((key) => key !== String(row[rowKey])) : [...selected, String(row[rowKey])])" /></td><td v-for="column in columns" :key="column.key" :data-label="localizeAdminLabel(column.key, column.label)" :data-priority="column.priority ?? 'secondary'">{{ column.sensitive ? '••••' : localizeAdminValue(row[column.key], column.key) }}</td><td v-if="$slots.actions" data-label="操作" data-priority="primary" class="v-admin-table__actions"><slot name="actions" :row="row" /></td></tr></tbody></table><p v-if="!rows.length">当前无数据。请调整筛选条件或检查数据源。</p></div></template>
